/**
 * The insight catalogue: how a business actually gets recommended by AI.
 *
 * This is the product's opinion, written down once and testable, rather than prose
 * regenerated by a model each time a customer asks.
 *
 * Every insight declares what it is grounded in, whether the business controls it, and how
 * we would know it worked. An insight that fails those three is advice, not a product
 * feature, and the difference matters: advice is what a customer can get free from a blog.
 *
 * The ordering principle throughout is honesty about leverage. The things that move AI
 * recommendations most for a local business are, in order: being unmistakably identifiable,
 * saying plainly what you are good for, and being consistent everywhere. Chasing coverage
 * you cannot control comes last, and is labelled as such.
 */
import type { Controllability } from '@autopilot/shared/domain.ts'

export type InsightCategory =
  | 'IDENTITY' // can an AI tell who and what you are?
  | 'ATTRIBUTES' // does it know what you are good for?
  | 'CONSISTENCY' // does your information agree with itself?
  | 'ACCESSIBILITY' // can it read your site at all?
  | 'STRUCTURE' // is the information machine-readable?
  | 'COVERAGE' // do the questions customers ask have answers on your site?
  | 'AUTHORITY' // does anyone else corroborate you?

export type Effort = 'MINUTES' | 'HOURS' | 'ONGOING'

export interface InsightStep {
  readonly he: string
  readonly en: string
}

export interface Insight {
  readonly key: string
  readonly category: InsightCategory
  readonly title: { he: string; en: string }
  /** Why this matters, in the customer's terms. Never SEO jargon. */
  readonly why: { he: string; en: string }
  /** Concrete steps. A business owner should be able to follow these without us. */
  readonly steps: readonly InsightStep[]
  readonly controllability: Controllability
  readonly effort: Effort
  /**
   * Expected leverage, 0..1. These are PRIORS, not measurements. The experiment engine
   * replaces them with observed outcomes as the dataset grows; until then they are stated
   * as beliefs and the UI presents them that way.
   */
  readonly expectedLeverage: number
  /** How the business would know it worked. An insight with no signal is not actionable. */
  readonly howYouWillKnow: { he: string; en: string }
  /** True when the product does this for the customer automatically. */
  readonly weDoThisForYou: boolean
  /** Verticals this applies to; empty means all. */
  readonly verticals: readonly string[]
}

