export const insightsFor = (vertical: string): readonly Insight[] =>
  INSIGHTS.filter((i) => i.verticals.length === 0 || i.verticals.includes(vertical))

/**
 * Ranked for a specific business.
 *
 * Weighted so that something we can act on today outranks something with a higher ceiling
 * that depends on other people. A list topped by "get press coverage" is a list that makes
 * a customer feel stuck.
 */
export const prioritizedInsights = (
  vertical: string,
  options: { readonly weakCategories?: readonly InsightCategory[] } = {},
): readonly Insight[] => {
  const weak = new Set(options.weakCategories ?? [])
  const controlWeight: Record<Controllability, number> = {
    CONTROLLED: 1,
    INFLUENCEABLE: 0.6,
    NOT_CONTROLLED: 0.3,
  }
  const effortWeight: Record<Effort, number> = { MINUTES: 1, HOURS: 0.85, ONGOING: 0.6 }

  return [...insightsFor(vertical)].sort((a, b) => {
    const score = (i: Insight): number =>
      i.expectedLeverage *
      controlWeight[i.controllability] *
      effortWeight[i.effort] *
      // A weakness we actually measured outranks a general prior.
      (weak.has(i.category) ? 1.5 : 1)
    return score(b) - score(a)
  })
}
